		timestamp: new Date().toISOString(),
	});
	const dbResult = getFeedbackDb(tmpDir);
	if (!dbResult.ok) return;
	const { db } = dbResult.value;
	db.prepare(
		`UPDATE feedback SET workflow_id = ?
